impl<T: gx::Real> Motor<(), T> {
    /// The squared norm: the scalar part of `x ~x`.
    #[inline(always)]
    pub fn norm_squared(self) -> T {
        let x = self.c;
        let t1 = x[5] * x[5];
        let t3 = x[7] * x[7];
        let t5 = x[9] * x[9];
        let t7 = x[15] * x[15];
        let t8 = x[0].mul_add(x[0], t1);
        let t9 = x[6].mul_add(x[6], t3);
        let t10 = t8 + t9;
        let t11 = x[8].mul_add(x[8], t5);
        let t12 = x[10].mul_add(x[10], t7);
        let t13 = t11 + t12;
        let t14 = t10 - t13;
        t14
    }

    /// The norm, `sqrt(|norm_squared|)`.
    #[inline(always)]
    pub fn norm(self) -> T {
        self.norm_squared().abs().sqrt()
    }

}

impl<T: gx::Real> gx::Log<Bivector<(), T>> for gx::Unit<Motor<(), T>> {
    /// The logarithm of a unit versor: the bivector `B` with `B.exp() == self`.
    #[inline]
    #[allow(unused_variables)]
    fn log(self) -> Bivector<(), T> {
        T::vectorize(#[inline(always)] move || {
        let x = self.into_inner().c;
        let p0 = x[15] * x[15];
        let p1 = -p0;
        let [h0, h1] = gx::study::log_coeffs_q(x[0], p1);
        let t0 = x[15] * h1;
        let t1 = x[11] * h1;
        let t2 = x[12] * h1;
        let t3 = x[13] * h1;
        let t4 = x[14] * h1;
        let t7 = x[9] * t3;
        let t8 = x[10] * t2;
        let t11 = x[8] * t3;
        let t12 = x[10] * t1;
        let t15 = x[8] * t2;
        let t16 = x[9] * t1;
        let t18 = x[5] * t1;
        let t20 = x[7] * t3;
        let t21 = x[5] * h0;
        let t23 = x[6] * h0;
        let t25 = x[7] * h0;
        let t28 = x[8] * h0;
        let t30 = x[9] * h0;
        let t32 = x[10] * h0;
        let t33 = x[1].mul_add(h0, t7);
        let t34 = x[5].mul_add(t4, t8);
        let t35 = t33 - t34;
        let t36 = x[2].mul_add(h0, t12);
        let t37 = x[6].mul_add(t4, t11);
        let t38 = t36 - t37;
        let t39 = x[3].mul_add(h0, t15);
        let t40 = x[7].mul_add(t4, t16);
        let t41 = t39 - t40;
        let t42 = x[4].mul_add(h0, t18);
        let t43 = x[6].mul_add(t2, t20);
        let t44 = t42 + t43;
        let t45 = (-x[8]).mul_add(t0, t21);
        let t46 = (-x[9]).mul_add(t0, t23);
        let t47 = (-x[10]).mul_add(t0, t25);
        let t48 = x[5].mul_add(t0, t28);
        let t49 = x[6].mul_add(t0, t30);
        let t50 = x[7].mul_add(t0, t32);
        Bivector::from_coeffs([t35, t38, t41, t44, t45, t46, t47, t48, t49, t50])
        })
    }
}

#[doc = "The odd subalgebra: reflections composed with motions."]
///
/// Blades, in coefficient order: `[e0, e1, e2, e3, e4, e023, e031, e012, e014, e024, e034, e123, e234, e314, e124, e01234]`.
///
/// `S` lists the open slots: `Odd` (that is, `Odd<()>`) is a value, `Odd<(A,)>` a
/// linear map from `A`, `Odd<(A, B)>` a bilinear map. `T` is the coefficient type.
#[repr(C)]
pub struct Odd<S: gx::Slots = (), T: gx::Coef = f32> {
    /// Coefficients, output first: `c[i]` is the slot array of blade `i`.
    pub c: [S::Arr<T>; 16],
}

impl<S: gx::Slots, T: gx::Coef> Clone for Odd<S, T> {
    #[inline(always)]
    fn clone(&self) -> Self {
        *self
    }
}

impl<S: gx::Slots, T: gx::Coef> Copy for Odd<S, T> {}

impl<S: gx::Slots, T: gx::Coef> PartialEq for Odd<S, T> {
    fn eq(&self, other: &Self) -> bool {
        self.c == other.c
    }
}

impl<S: gx::Slots, T: gx::Coef> core::fmt::Debug for Odd<S, T> {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        let mut d = f.debug_struct("Odd");
        for (b, c) in <Odd as gx::Kind>::BLADES.iter().zip(self.c.iter()) {
            d.field(b, c);
        }
        d.finish()
    }
}

impl gx::Kind for Odd {
    const N: usize = 16;
    const NAME: &'static str = "Odd";
    const MODULE: &'static str = module_path!();
    const BLADES: &'static [&'static str] = &["e0", "e1", "e2", "e3", "e4", "e023", "e031", "e012", "e014", "e024", "e034", "e123", "e234", "e314", "e124", "e01234"];
    type Arr<X: gx::Elem> = [X; 16];
    type Mv<S: gx::Slots, T: gx::Coef> = Odd<S, T>;
    type Scalar = Scalar;
    #[inline(always)]
    fn arr_from_fn<X: gx::Elem>(mut f: impl FnMut(usize) -> X) -> [X; 16] {
        [f(0), f(1), f(2), f(3), f(4), f(5), f(6), f(7), f(8), f(9), f(10), f(11), f(12), f(13), f(14), f(15)]
    }
    #[inline(always)]
    fn arr_map<X: gx::Elem, Y: gx::Elem>(a: &[X; 16], mut f: impl FnMut(&X) -> Y) -> [Y; 16] {
        [f(&a[0]), f(&a[1]), f(&a[2]), f(&a[3]), f(&a[4]), f(&a[5]), f(&a[6]), f(&a[7]), f(&a[8]), f(&a[9]), f(&a[10]), f(&a[11]), f(&a[12]), f(&a[13]), f(&a[14]), f(&a[15])]
    }
    #[inline(always)]
    fn arr_zip<X: gx::Elem, Y: gx::Elem, Z: gx::Elem>(
        a: &[X; 16],
        b: &[Y; 16],
        mut f: impl FnMut(&X, &Y) -> Z,
    ) -> [Z; 16] {
        [f(&a[0], &b[0]), f(&a[1], &b[1]), f(&a[2], &b[2]), f(&a[3], &b[3]), f(&a[4], &b[4]), f(&a[5], &b[5]), f(&a[6], &b[6]), f(&a[7], &b[7]), f(&a[8], &b[8]), f(&a[9], &b[9]), f(&a[10], &b[10]), f(&a[11], &b[11]), f(&a[12], &b[12]), f(&a[13], &b[13]), f(&a[14], &b[14]), f(&a[15], &b[15])]
    }
}

