impl<S: gx::Slots, T: gx::Coef> gx::Transform<Quadvector<S, T>> for gx::Unit<Vector<(), T>> {
    type Output = Quadvector<S, T>;
    #[inline(always)]
    fn transform(self, x: Quadvector<S, T>) -> Quadvector<S, T> {
        let v = self.into_inner().c;
        #[cfg(feature = "check-units")]
        {
        let u1 = v[2] * v[2];
        let u4 = v[1].mul_add(v[1], u1);
        let u5 = v[3].mul_add(v[3], u4);
        let u6 = v[4].mul_add(v[4], T::from_i64(1));
        let u7 = u5 - u6;
            T::check_unit(&[u7]);
        }
        if let Some(xv) = gx::slots::values::<S, T, 5>(&x.c) {
        let t1 = v[1] * xv[0];
        let t4 = v[4] * xv[3];
        let t5 = v[0].mul_add(xv[4], t1);
        let t6 = v[2].mul_add(xv[1], t5);
        let t7 = v[3].mul_add(xv[2], t4);
        let t8 = t6 + t7;
        let t9 = v[1] * t8;
        let t10 = v[2] * t8;
        let t11 = v[3] * t8;
        let t12 = v[4] * t8;
        let t13 = t9 * T::from_i64(2);
        let t15 = v[2] * v[2];
        let t16 = v[3] * v[3];
        let t18 = v[1].mul_add(v[1], t15);
        let t19 = (-v[4]).mul_add(v[4], t16);
        let t20 = t18 + t19;
        let t22 = (-xv[0]).mul_add(t20, t13);
        let t23 = t10 * T::from_i64(2);
        let t25 = (-xv[1]).mul_add(t20, t23);
        let t26 = t11 * T::from_i64(2);
        let t28 = (-xv[2]).mul_add(t20, t26);
        let t30 = xv[3] * t20;
        let t31 = t12.mul_add(T::from_i64(2), t30);
        let t32 = -t31;
        let t33 = -xv[4];
        let t34 = t20 * t33;
            return Quadvector { c: gx::slots::from_values::<S, T, 5>([t22, t25, t28, t32, t34]) };
        }
        let m0 = v[1] * v[1];
        let m1 = v[2] * v[2];
        let m2 = v[3] * v[3];
        let m3 = v[4] * v[4];
        let m4 = v[1] * v[2];
        let m5 = v[1] * v[3];
        let m6 = v[1] * v[4];
        let m7 = v[2] * v[3];
        let m8 = v[2] * v[4];
        let m9 = v[3] * v[4];
        let m10 = v[0] * v[1];
        let m11 = v[0] * v[2];
        let m12 = v[0] * v[3];
        let m13 = v[0] * v[4];
        let m14 = m0 + m1;
        let m15 = m2 - m3;
        let m16 = m0 - m1;
        let m17 = m2 + m3;
        let m18 = m16 - m15;
        let m19 = m4 * T::from_i64(2);
        let m20 = m5 * T::from_i64(2);
        let m21 = m6 * T::from_i64(2);
        let m22 = m10 * T::from_i64(2);
        let m23 = m15 + m16;
        let m24 = -m23;
        let m25 = m7 * T::from_i64(2);
        let m26 = m8 * T::from_i64(2);
        let m27 = m11 * T::from_i64(2);
        let m28 = m17 - m14;
        let m29 = m9 * T::from_i64(2);
        let m30 = m12 * T::from_i64(2);
        let m31 = -m21;
        let m32 = -m26;
        let m33 = -m29;
        let m34 = m14 + m17;
        let m35 = -m34;
        let m36 = m13 * T::from_i64(2);
        let m37 = -m36;
        let m38 = m14 + m15;
        let m39 = -m38;
        let x = x.c.map(gx::SlotArr::<S, T>);
        Quadvector { c: [(x[0].scale(m18) + x[1].scale(m19) + x[2].scale(m20) + x[3].scale(m21) + x[4].scale(m22)).0, (x[0].scale(m19) + x[1].scale(m24) + x[2].scale(m25) + x[3].scale(m26) + x[4].scale(m27)).0, (x[0].scale(m20) + x[1].scale(m25) + x[2].scale(m28) + x[3].scale(m29) + x[4].scale(m30)).0, (x[0].scale(m31) + x[1].scale(m32) + x[2].scale(m33) + x[3].scale(m35) + x[4].scale(m37)).0, (x[4].scale(m39)).0] }
    }
}

