#[cfg(feature = "batch")]
impl gx::batch::SandwichKernel<Trivector, gx::batch::Plain> for Motor {
    type Y = Trivector;
    type Versor<T: gx::Coef> = Motor<(), T>;
    type Prepared<T: gx::Coef> = gx::Prepared<Motor, Trivector, T, 67>;
    #[inline(always)]
    fn wrap<T: gx::Coef>(v: Motor<(), T>) -> Motor<(), T> {
        v
    }
    #[inline(always)]
    fn unwrap<T: gx::Coef>(v: Motor<(), T>) -> Motor<(), T> {
        v
    }
    #[inline(always)]
    fn prepare<T: gx::Coef>(v: Motor<(), T>) -> gx::Prepared<Motor, Trivector, T, 67> {
        gx::Prepare::<Trivector>::prepare(v)
    }
    #[inline(always)]
    fn map_prepared<T: gx::Coef, W: gx::Coef>(p: gx::Prepared<Motor, Trivector, T, 67>, mut f: impl FnMut(T) -> W) -> gx::Prepared<Motor, Trivector, W, 67> {
        let m = p.m;
        gx::Prepared::from_entries([f(m[0]), f(m[1]), f(m[2]), f(m[3]), f(m[4]), f(m[5]), f(m[6]), f(m[7]), f(m[8]), f(m[9]), f(m[10]), f(m[11]), f(m[12]), f(m[13]), f(m[14]), f(m[15]), f(m[16]), f(m[17]), f(m[18]), f(m[19]), f(m[20]), f(m[21]), f(m[22]), f(m[23]), f(m[24]), f(m[25]), f(m[26]), f(m[27]), f(m[28]), f(m[29]), f(m[30]), f(m[31]), f(m[32]), f(m[33]), f(m[34]), f(m[35]), f(m[36]), f(m[37]), f(m[38]), f(m[39]), f(m[40]), f(m[41]), f(m[42]), f(m[43]), f(m[44]), f(m[45]), f(m[46]), f(m[47]), f(m[48]), f(m[49]), f(m[50]), f(m[51]), f(m[52]), f(m[53]), f(m[54]), f(m[55]), f(m[56]), f(m[57]), f(m[58]), f(m[59]), f(m[60]), f(m[61]), f(m[62]), f(m[63]), f(m[64]), f(m[65]), f(m[66])])
    }
    #[inline(always)]
    fn apply_prepared<T: gx::Coef>(p: gx::Prepared<Motor, Trivector, T, 67>, x: Trivector<(), T>) -> Trivector<(), T> {
        gx::Transform::transform(p, x)
    }
    #[inline(always)]
    fn apply<T: gx::Coef>(v: Motor<(), T>, x: Trivector<(), T>) -> Trivector<(), T> {
        gx::Transform::transform(v, x)
    }
}

