impl<S: gx::Slots, T: gx::Coef> gx::TransformInv<Multivector<S, T>> for Motor<(), T> {
    type Output = Multivector<S, T>;
    #[inline(always)]
    fn transform_inv(self, x: Multivector<S, T>) -> Multivector<S, T> {
        gx::Transform::transform(self.reverse(), x)
    }
}

