#[cfg(feature = "bytemuck")]
/// Alias of [`QuadvectorGpu`].
pub type EventGpu = QuadvectorGpu;

#[cfg(feature = "bytemuck")]
/// Alias of [`QuadvectorGpu`].
pub type PointGpu = QuadvectorGpu;

#[cfg(feature = "bytemuck")]
/// Alias of [`MotorGpu`].
pub type EvenGpu = MotorGpu;

